/**
 * MSRIM ERP — Import Term 4 Students from Students_Report_2.xlsx
 * Source: backend/database/students_import.json  (generated by PowerShell)
 * Run: node backend/database/import_students.js
 *
 * Strategy:
 *  - Keeps all existing students intact (INSERT OR IGNORE on username/email)
 *  - Creates a user account per student (username = email prefix before @)
 *  - Default password = Registration ID (e.g. 251051)  ← change via Admin Privileges
 *  - Creates student record linked to the user
 *  - Maps section A-E to program_id=1 (PGDM), semester=4, batch_year=2025
 */

const path   = require('path');
const bcrypt = require('bcryptjs');
const { DatabaseSync } = require('node:sqlite');

const DB_PATH      = path.join(__dirname, 'msrim_erp.db');
const IMPORT_FILE  = path.join(__dirname, 'students_import.json');

const db      = new DatabaseSync(DB_PATH);
const records = JSON.parse(require('fs').readFileSync(IMPORT_FILE, 'utf8').replace(/^﻿/, ''));

// ── Helpers ───────────────────────────────────────────────────────────────────
const hashPwd = (pwd) => bcrypt.hashSync(pwd, 10);

// Extract a clean username from email (part before @)
function toUsername(email, regId) {
  if (email && email.includes('@')) return email.split('@')[0].toLowerCase();
  return 'stu' + regId;
}

// Map section letter to a numeric value (A=1 … E=5) for roll_number prefix
const sectionNum = { A: 1, B: 2, C: 3, D: 4, E: 5 };

// Map gender field
function normaliseGender(g) {
  if (!g || g === '--' || g === 'unknown') return null;
  return g.toLowerCase();
}

// ── Prepared statements ───────────────────────────────────────────────────────
const insertUser = db.prepare(`
  INSERT OR IGNORE INTO users
    (username, password, role, name, email, phone, department, is_active)
  VALUES (?, ?, 'student', ?, ?, ?, 'Management Studies', 1)
`);

const getUserId = db.prepare(`SELECT id FROM users WHERE username = ?`);

const insertStudent = db.prepare(`
  INSERT OR IGNORE INTO students
    (user_id, enrollment_number, program_id, semester, batch_year,
     section, gender, admission_date, status, created_at)
  VALUES (?, ?, 1, 4, 2025, ?, ?, ?, 'active', datetime('now'))
`);

const checkStudent = db.prepare(`SELECT id FROM students WHERE enrollment_number = ?`);

// ── Import loop ───────────────────────────────────────────────────────────────
let created = 0, skipped = 0, errors = 0;

console.log(`\nImporting ${records.length} students…\n`);

for (const rec of records) {
  try {
    const username   = toUsername(rec.email, rec.reg_id);
    const password   = hashPwd(rec.reg_id);          // default: registration ID
    const gender     = normaliseGender(rec.gender);
    const admDate    = rec.doj && rec.doj !== '--' ? rec.doj : '2025-07-28';
    const enrollment = `MSRIM-PGDM-25-${rec.reg_id}`;

    // 1. Create user
    const uRes = insertUser.run(username, password, rec.name, rec.email, rec.phone || null);

    // 2. Get user ID (whether just created or already existed)
    const user = getUserId.get(username);
    if (!user) { errors++; console.error(`  ✗ Could not get user for ${rec.name}`); continue; }

    // 3. Create student record
    const sRes = insertStudent.run(
      user.id, enrollment, rec.section, gender, admDate
    );

    if (sRes.changes > 0) {
      created++;
      if (created <= 10 || created % 50 === 0)
        console.log(`  ✓ [${created}] ${rec.reg_id} | ${rec.name} | Sec:${rec.section}`);
    } else {
      skipped++;
    }

  } catch (err) {
    errors++;
    console.error(`  ✗ Error for ${rec.reg_id} (${rec.name}): ${err.message}`);
  }
}

// ── Summary ───────────────────────────────────────────────────────────────────
console.log(`
════════════════════════════════════════════════
✅  Import complete
    Created : ${created} students
    Skipped : ${skipped} (already existed)
    Errors  : ${errors}
════════════════════════════════════════════════

📋  Login for any student:
    Username : <email prefix>  e.g.  apadmavati251051
    Password : <registration ID>  e.g.  251051
    (change passwords via Admin → Admin Privileges)
`);

// ── Quick verification ────────────────────────────────────────────────────────
const total   = db.prepare("SELECT COUNT(*) as n FROM students").get().n;
const bySection = db.prepare(`
  SELECT section, COUNT(*) as n FROM students
  WHERE batch_year = 2025 GROUP BY section ORDER BY section
`).all();

console.log(`Total students in DB now: ${total}`);
console.log('2025 batch by section:', bySection.map(r => `${r.section}:${r.n}`).join(', '));
